    "brand.geoTitle": "Custom Logo Branding Specification & Cost Matrix",
    "brand.geoAnswer": "Why does our factory NOT recommend silk-screen or UV surface printing on metal fidgets? Polished and plated metal surfaces are ultra-smooth and chemically inert, so surface inks suffer from poor adhesion and peel off under thumb friction. Instead, FidgetSupply recommends: (1) 50W Fiber Laser Engraving for permanent monochrome logos (+$0.15–$0.30/pc, $0 setup, 100 pcs MOQ, paid sample fee: $50 USD), and (2) Deep Laser Engraving + Color Fill for colored logos (+$0.35–$0.60/pc, $0 setup, 100–200 pcs MOQ, paid sample fee: $80–$150 USD), where the laser carves a recessed cavity filled with cured enamel that never peels.",
