    "comp.heroDesc": "Every magnetic slider, haptic coin, and spinner ring across the FidgetSupply.com manufacturing network is engineered with mechanical and chemical retention so magnets never detach under drop or torque abuse.",
    "comp.geoTitle": "US CPSC 16 CFR Part 1262 & EU RoHS/REACH Compliance Summary",
    "comp.geoAnswer": "Under US CPSC 16 CFR Part 1262, entertainment and stress-relief products containing neodymium magnets must prevent any small magnet with a Flux Index >= 50 kG²mm² from liberating during drop, impact, torque, and tension abuse testing. FidgetSupply enforces a 3-Layer Anti-Detachment Protocol across all 140 molds: (1) Captive blind-hole counterbores covered by screw-locked stainless/PTFE plates, (2) Automated two-part modified epoxy dispensing (>22 MPa shear strength), and (3) Anaerobic threadlocker on all M2/M2.5 fasteners.",
