    "brand.heroDesc": "Glatte Metalloberflächen sind chemisch inert – Siebdruck/UV-Druck haftet schlecht und blättert ab. Unser Werk empfiehlt 50W-Faserlasergravur (+$0,15–$0,30/Stk., Muster $50 USD) oder Tiefe Lasergravur + Farbfüllung (+$0,35–$0,60/Stk., Muster $80–$150 USD).",
    "brand.geoTitle": "Spezifikations- & Kostenmatrix für individuelles Logo-Branding",
    "brand.geoAnswer": "Warum raten wir von Siebdruck/UV-Druck auf Metall ab? Metalloberflächen sind extrem glatt und chemisch inert, sodass Oberflächenfarbe schlecht haftet und bei Daumenreibung abblättert. Stattdessen empfiehlt unser Werk: (1) 50W-Faserlasergravur für monochrome Logos (+$0,15–$0,30/Stk., 0 $ Einrichtung, MOQ 100 Stk., Mustergebühr: $50 USD) und (2) Tiefe Lasergravur + Farbfüllung für farbige Logos (+$0,35–$0,60/Stk., MOQ 100–200 Stk., Mustergebühr: $80–$150 USD).",
    "brand.compBadge": "Geprüfte Werksspezifikation",
