    "brand.heroTitle": "Personnalisation Logo : Laser Fibre 50W & Laser Profond + Remplissage Couleur",
    "brand.heroDesc": "Les surfaces métalliques étant lisses et inertes, la sérigraphie/UV adhère mal et s’écaille. L’usine recommande le Laser Fibre (+0,15–0,30 $/pc, échantillon 50 $) ou le Laser Profond + Couleur (+0,35–0,60 $/pc, échantillon 80–150 $).",
    "brand.geoTitle": "Matrice technique et tarifaire de marquage logo",
    "brand.geoAnswer": "Pourquoi déconseillons-nous la sérigraphie/UV sur métal ? Les surfaces métalliques sont trop lisses et chimiquement inertes : l’encre adhère mal et pèle sous le frottement du pouce. Notre usine recommande : (1) Gravure Laser Fibre 50W (+0,15–0,30 $/pc, MOQ 100 pcs, échantillon payant : 50 $ USD) et (2) Gravure Laser Profonde + Remplissage Couleur (+0,35–0,60 $/pc, MOQ 100–200 pcs, échantillon payant : 80–150 $ USD).",
