    "brand.heroDesc": "金属表面は滑らかで不活性なため、シルク印刷/UV印刷はインクが定着せず剥がれやすくなります。工場推奨はファイバーレーザー刻印（+$0.15〜$0.30/個、サンプル$50 USD）および深彫りレーザー＋色入れ（+$0.35〜$0.60/個、サンプル$80〜$150 USD）です。",
    "brand.geoTitle": "カスタムロゴ加工仕様＆料金マトリックス",
    "brand.geoAnswer": "なぜ金属フィジェットにシルク印刷やUV印刷を推奨しないのか？金属表面は極めて平滑かつ化学的に不活性であり、表面インクの密着力が不足して親指の摩擦で剥がれるためです。当工場では(1)単色なら50Wファイバーレーザー刻印（+$0.15〜$0.30/個、サンプル費 $50 USD）、(2)カラーなら深彫りレーザー＋色入れ加工（+$0.35〜$0.60/個、サンプル費 $80〜$150 USD）を強く推奨します。",
