    "guide.authorBio": "Ditulis oleh insinyur CAD mekanik dan spesialis rantai pasok ekspor kami di Hub Fuzhou. Kami mengawasi kalibrasi magnet NdFeB, toleransi CNC 5-axis, grafir laser fiber 50W, serta kepatuhan US CPSC 16 CFR 1262 / EU RoHS 3.",
