    "about.heroDesc": "Kami menghubungkan pembeli grosir global dengan bengkel pengerjaan logam spesialis di Tiongkok — meliputi die-casting paduan seng, pemesinan CNC, perakitan magnet neodymium, dan branding laser / color-fill — dikoordinasikan melalui hub ekspor kami di Fuzhou.",
    "about.geoTitle": "Platform Pengadaan & Rantai Pasok Terintegrasi untuk Industri Fidget EDC Logam Tiongkok",
    "about.geoAnswer": "Kami menghubungkan pembeli grosir global dengan bengkel pengerjaan logam spesialis di Tiongkok — meliputi die-casting paduan seng, pemesinan CNC, perakitan magnet neodymium, dan branding laser / color-fill — dikoordinasikan melalui hub ekspor kami di Fuzhou. Model ini menggunakan cetakan produksi kami yang sudah siap pakai. Tersedia untuk grosir polos (MOQ 50 pcs) atau kustomisasi logo via Grafir Laser Fiber dan Cetak UV (MOQ 100 pcs).",
    "about.card1Title": "1. Bengkel Die-Casting & Pemesinan CNC",
    "about.card1Desc": "Paduan Seng Die-Cast · Baja Tahan Karat 303 / 304 / 316 · Aluminium Anodized 6061 / 6063 · PEI (Ultem) / Serat Karbon / Zirkonium",
    "about.card2Title": "2. Perakitan Magnet & Bearing Presisi",
    "about.card2Desc": "N35–N52 · R188 · ✓ Magnet Terkunci US CPSC 16 CFR 1262",
