    "about.card3Desc": "Pilih dari 140 Cetakan Logam Siap Pakai + Tambahkan Logo Kustom Anda mulai MOQ 100 pcs. Foto sampel fisik dalam 48 jam, produksi 7–10 hari. · Case EVA Kustom & Kotak Hadiah",
