    "guide.authorBio": "أعده مهندسو التصميم الميكانيكي ومتخصصو التصدير في مركز فوتشو الصناعي. نشرف على معايرة مغناطيس النيوديميوم NdFeB، ودقة التصنيع الرقمي CNC خماسي المحاور، وحفر الليزر بقدرة 50 واط، والامتثال لمعايير US CPSC 16 CFR 1262 / EU RoHS 3.",
