    "about.heroBadge": "منصة التوريد وسلسلة الإمداد المتكاملة لصناعة ألعاب الفيدجت المعدنية EDC في الصين",
    "about.heroTitle": "منصتك المتكاملة للتوريد وسلاسل الإمداد لصناعة فيدجت المعادن EDC في الصين",
    "about.heroDesc": "نربط مشتري الجملة العالميين بورش تصنيع المعادن المتخصصة في الصين — من صب سبائك الزنك والتصنيع الرقمي CNC إلى تجميع مغناطيس النيوديميوم وطباعة الليزر/UV — بتنسيق كامل عبر مركز التصدير في فوتشو.",
    "about.geoTitle": "منصتك المتكاملة للتوريد وسلاسل الإمداد لصناعة فيدجت المعادن EDC في الصين",
    "about.geoAnswer": "نربط مشتري الجملة العالميين بورش تصنيع المعادن المتخصصة في الصين — من صب سبائك الزنك والتصنيع الرقمي CNC إلى تجميع مغناطيس النيوديميوم وطباعة الليزر/UV — بتنسيق كامل عبر مركز التصدير في فوتشو. يستخدم هذا الموديل قالب الإنتاج الجاهز لدينا. متاح فوراً للجملة بدون شعار (الحد الأدنى 50 قطعة) أو مع حفر الليزر والطباعة الملونة UV (الحد الأدنى 100 قطعة).",
    "about.card1Title": "1. ورش صب القوالب والتصنيع الرقمي CNC",
    "about.card1Desc": "سبائك الزنك المصبوبة · فولاذ مقاوم للصدأ 303 / 304 / 316 · ألومنيوم مؤكسد 6061 / 6063 · إيثر بولي إيميد PEI / ألياف الكربون / الزركونيوم",
    "about.card2Title": "2. تجميع وفحص المغناطيس والمحامل",
    "about.card2Desc": "N35–N52 · R188 · ✓ مغناطيس مؤمّن وفق معيار US CPSC 16 CFR 1262",
    "about.card3Title": "3. تخصيص الشعارات وتجميع شحنات التصدير",
    "about.card3Desc": "140 قالبًا جاهزًا + حفر بالليزر أو طباعة حريرية أو حفر عميق ملون بدءًا من 100 قطعة (العينة 10–15 يومًا) · حقائب EVA وصناديق هدايا مخصصة",
